using NUnit.Framework;

namespace Enterprise.Customs.AU.Declaration.Business.Testing
{
	sealed class EXDOCComplianceStatusCodesForCusEntryNumberTest : TestCase
	{
		public void TestGetCodeFromEXDOCComplianceStatusCode()
		{
			AssertEquals(EXDOCComplianceStatusCodesForCusEntryNumber.Codes.CancCancelled, EXDOCComplianceStatusCodesForCusEntryNumber.GetCodeFromEXDOCComplianceStatusCode(EXDOCComplianceStatusCodes.Codes.Cancelled));
			AssertEquals(EXDOCComplianceStatusCodesForCusEntryNumber.Codes.CompCompleted, EXDOCComplianceStatusCodesForCusEntryNumber.GetCodeFromEXDOCComplianceStatusCode(EXDOCComplianceStatusCodes.Codes.Completed));
			AssertEquals(EXDOCComplianceStatusCodesForCusEntryNumber.Codes.CtrdCertificateReady, EXDOCComplianceStatusCodesForCusEntryNumber.GetCodeFromEXDOCComplianceStatusCode(EXDOCComplianceStatusCodes.Codes.CertificateReady));
			AssertEquals(EXDOCComplianceStatusCodesForCusEntryNumber.Codes.EmctEmergencyHealthCertificate, EXDOCComplianceStatusCodesForCusEntryNumber.GetCodeFromEXDOCComplianceStatusCode(EXDOCComplianceStatusCodes.Codes.RexEmergencyHealthCertificate));
			AssertEquals(EXDOCComplianceStatusCodesForCusEntryNumber.Codes.EmhcEmergencyHealthCertificate, EXDOCComplianceStatusCodesForCusEntryNumber.GetCodeFromEXDOCComplianceStatusCode(EXDOCComplianceStatusCodes.Codes.RfpEmergencyHealthCertificate));
			AssertEquals(EXDOCComplianceStatusCodesForCusEntryNumber.Codes.FinlFinal, EXDOCComplianceStatusCodesForCusEntryNumber.GetCodeFromEXDOCComplianceStatusCode(EXDOCComplianceStatusCodes.Codes.Final));
			AssertEquals(EXDOCComplianceStatusCodesForCusEntryNumber.Codes.HcrdHealthCertificateReady, EXDOCComplianceStatusCodesForCusEntryNumber.GetCodeFromEXDOCComplianceStatusCode(EXDOCComplianceStatusCodes.Codes.HealthCertificateReady));
			AssertEquals(EXDOCComplianceStatusCodesForCusEntryNumber.Codes.InitInitial, EXDOCComplianceStatusCodesForCusEntryNumber.GetCodeFromEXDOCComplianceStatusCode(EXDOCComplianceStatusCodes.Codes.Initial));
			AssertEquals(EXDOCComplianceStatusCodesForCusEntryNumber.Codes.InspInspected, EXDOCComplianceStatusCodesForCusEntryNumber.GetCodeFromEXDOCComplianceStatusCode(EXDOCComplianceStatusCodes.Codes.Inspected));
			AssertEquals(EXDOCComplianceStatusCodesForCusEntryNumber.Codes.OrdrOrder, EXDOCComplianceStatusCodesForCusEntryNumber.GetCodeFromEXDOCComplianceStatusCode(EXDOCComplianceStatusCodes.Codes.Order));
			AssertEquals(EXDOCComplianceStatusCodesForCusEntryNumber.Codes.ReviewInReview, EXDOCComplianceStatusCodesForCusEntryNumber.GetCodeFromEXDOCComplianceStatusCode(EXDOCComplianceStatusCodes.Codes.Review));
			AssertEquals(EXDOCComplianceStatusCodesForCusEntryNumber.Codes.SuspSuspended, EXDOCComplianceStatusCodesForCusEntryNumber.GetCodeFromEXDOCComplianceStatusCode(EXDOCComplianceStatusCodes.Codes.Suspended));
			AssertEquals(EXDOCComplianceStatusCodesForCusEntryNumber.Codes.WtdrnWithdrawn, EXDOCComplianceStatusCodesForCusEntryNumber.GetCodeFromEXDOCComplianceStatusCode(EXDOCComplianceStatusCodes.Codes.Withdrawn));
			AssertEquals("Non Existant Code", string.Empty, EXDOCTransportModeCodes.GetEXDOCCodeFromTransportModeCode("XXX"));
		}
	}
}
